1	import React, { useState } from 'react';
2	import { createRoot } from 'react-dom/client';
3	import { routes } from './router/routes';
4	
5	// Minimal base shell. Features register routes under features/<name>/route.tsx (discovered by
6	// router/routes.ts); the shell renders the nav and the selected page. Every observable element
7	// carries a stable data-testid, never renamed/removed (CLAUDE.md).
8	function App() {
9	  const [currentId, setCurrentId] = useState<string | null>(null);
10	  const current = routes.find((r) => r.id === currentId) ?? null;
11	
12	  return (
13	    <div data-testid="app-root">
14	      <nav data-testid="app-nav">
15	        OfficeHQ
16	        {routes.map((r) => (
17	          <button
18	            key={r.id}
19	            data-testid={`nav-${r.id}`}
